SELECT t.id AS task_id, t.series_code AS series_code, t.series_name AS series_name, COALESCE(t.display_title,'') AS display_title, t.status AS status, (SELECT COUNT(*) FROM textbook_import_chunk c WHERE c.task_id = t.id) AS chunk_total, (SELECT COUNT(*) FROM textbook_import_chunk c2 WHERE c2.task_id = t.id AND c2.status IN ('待处理','处理中')) AS pending_count, (SELECT COUNT(*) FROM textbook_import_draft d WHERE d.task_id = t.id) AS draft_total, t.created_at AS created_at FROM textbook_import_task t WHERE COALESCE(t.subject_id,1) = CAST(:subject_id AS INTEGER) ORDER BY t.id DESC
